#include "MasterLibrary.hpp"
#include <QStandardPaths>
#include <QSettings>
#include <QDir>
#include <QFile>
#include <QSaveFile>
#include <QTemporaryDir>
#include <QJsonDocument>
#include <QJsonObject>
#include <QJsonArray>
#include <QLockFile>
#include <QUuid>
#include <QDateTime>
#include <QCryptographicHash>
#include <QRegularExpression>
#include <algorithm>
#include <stdexcept>
namespace astro::app {
namespace {
void check(std::stop_token s){if(s.stop_requested())throw std::runtime_error("Cancelled. Previous results are preserved.");}
QString root(){return QSettings().value("calibration/libraryDirectory",QStandardPaths::writableLocation(QStandardPaths::AppDataLocation)+"/calibration-masters").toString();}
QVariantList inventory(){QFile file(root()+"/library.json");if(!file.exists())return {};if(file.size()>2097152||!file.open(QIODevice::ReadOnly))throw std::runtime_error("Cannot read the master library.");QJsonParseError error;const auto doc=QJsonDocument::fromJson(file.readAll(),&error);if(error.error!=QJsonParseError::NoError||!doc.isObject()||doc.object()["version"].toInt()!=1||!doc.object()["masters"].isArray())throw std::runtime_error("Invalid master library.");const auto rows=doc.object()["masters"].toArray().toVariantList();if(rows.size()>1000)throw std::runtime_error("Invalid master library.");for(const auto& v:rows){const auto r=v.toMap();if(!QRegularExpression("^[a-f0-9-]{36}$").match(r["id"].toString()).hasMatch()||!QRegularExpression("^[a-f0-9]{64}$").match(r["hash"].toString()).hasMatch()||!QStringList{"Dark","Bias","Flat","DarkFlat"}.contains(r["role"].toString()))throw std::runtime_error("Invalid master library.");}return rows;}
void save(const QVariantList& rows){QSaveFile file(root()+"/library.json");const auto bytes=QJsonDocument(QJsonObject{{"version",1},{"masters",QJsonArray::fromVariantList(rows)}}).toJson();if(bytes.size()>2097152||!file.open(QIODevice::WriteOnly)||file.write(bytes)!=bytes.size()||!file.commit())throw std::runtime_error("Cannot save the master library.");}
double median(std::vector<float> a){const auto mid=a.begin()+a.size()/2;std::nth_element(a.begin(),mid,a.end());return *mid;}
}
QString calibrationFileHash(const QString& path,std::stop_token stop){QFile file(path);if(!file.open(QIODevice::ReadOnly))throw std::runtime_error("Master file is missing or unreadable.");QCryptographicHash hash(QCryptographicHash::Sha256);while(!file.atEnd()){check(stop);const auto b=file.read(1048576);if(b.isEmpty()&&file.error()!=QFile::NoError)throw std::runtime_error("Cannot read master file.");hash.addData(b);}check(stop);return QString::fromLatin1(hash.result().toHex());}
QVariantMap calibrationMetadata(const recording::AstroImage& a){QVariantMap r{{"width",a.width},{"height",a.height},{"channels",a.channels},{"bayer",QString::fromUtf8(domain::to_string(a.bayer).data())},{"camera",QString::fromStdString(a.camera)},{"binX",a.binX},{"binY",a.binY},{"filter",QString::fromStdString(a.filter)},{"exposure",a.exposure},{"aduScale",a.originalScale},{"master",!a.masterRole.empty()},{"masterFlat",a.normalizedMasterFlat},{"masterCount",a.masterCount},{"rejectedSamples",qulonglong(a.masterRejected)}};if(a.hasGain)r["gain"]=a.gain;if(a.hasTemperature)r["temperature"]=a.temperature;if(a.hasOffset)r["offset"]=a.offset;return r;}
QVariantMap masterCompatibility(const QVariantMap& master,const QVariantList& rows){QStringList missing,errors;int considered=0;const auto role=master["role"].toString();for(const auto& v:rows){const auto l=v.toMap();if(l["role"]!=(role=="DarkFlat"?"Flat":"Light")||!l["selected"].toBool())continue;if(role=="Flat"&&master["group"]!=l["group"])continue;++considered;
 for(const auto& key:{"width","height","channels","bayer"})if(master[key]!=l[key])errors<<QString::fromUtf8(key);
 for(const auto& key:{"camera","binX","binY","gain","offset"}){const bool unknown=!master.contains(key)||!l.contains(key)||(QString(key)=="camera"?(master[key].toString().isEmpty()||l[key].toString().isEmpty()):(QString(key).startsWith("bin")&&(master[key].toInt()<=0||l[key].toInt()<=0)));if(unknown)missing<<QString::fromUtf8(key);else if(QString(key)=="camera"?master[key].toString()!=l[key].toString():std::abs(master[key].toDouble()-l[key].toDouble())>.01)errors<<QString::fromUtf8(key);}
 if(role=="Dark"||role=="DarkFlat"){if(!master.contains("temperature")||!l.contains("temperature"))missing<<"temperature";else if(std::abs(master["temperature"].toDouble()-l["temperature"].toDouble())>2)errors<<"temperature";if(master["exposure"].toDouble()<=0||l["exposure"].toDouble()<=0)missing<<"exposure";else if(std::abs(master["exposure"].toDouble()-l["exposure"].toDouble())>std::max(.01,l["exposure"].toDouble()*.01))errors<<"exposure";}
 if(role=="Flat"&&!master["filter"].toString().isEmpty()&&!l["filter"].toString().isEmpty()&&master["filter"].toString()!=l["filter"].toString())errors<<"filter";
 }if(!considered)errors<<"selected lights / filter group";missing.removeDuplicates();errors.removeDuplicates();return {{"compatibility",errors.isEmpty()?(missing.isEmpty()?0:1):2},{"missing",missing.join(", ")},{"mismatch",errors.join(", ")}};}
QVariantList calibrationMasterInventory(){auto rows=inventory();for(auto& v:rows){auto r=v.toMap();r["path"]=root()+"/"+r["id"].toString()+".fits";v=r;}return rows;}
QVariantMap calibrationMaster(const QString& id,std::stop_token stop){for(const auto& v:calibrationMasterInventory()){auto r=v.toMap();if(r["id"]==id){if(calibrationFileHash(r["path"].toString(),stop)!=r["hash"].toString())throw std::runtime_error("Master integrity check failed. Import an intact copy.");return r;}}throw std::runtime_error("Master not found in the library.");}
QVariantMap storeCalibrationMaster(recording::AstroImage image,const QString& name,std::stop_token stop){check(stop);if(name.trimmed().isEmpty()||name.size()>120||!QStringList{"Dark","Flat","Bias","DarkFlat"}.contains(QString::fromStdString(image.masterRole))||image.samples.empty()||(image.masterRole=="Flat"&&!image.normalizedMasterFlat))throw std::runtime_error("Invalid master name, role or flat calibration.");
 std::vector<float> sample;double nonfinite=0,zero=0,minimum=INFINITY,maximum=-INFINITY;const auto step=std::max(std::size_t(1),image.samples.size()/100000);for(std::size_t i=0;i<image.samples.size();++i){if(i%65536==0)check(stop);const float v=image.samples[i];if(!std::isfinite(v)){++nonfinite;continue;}zero+=v<=0;minimum=std::min(minimum,double(v));maximum=std::max(maximum,double(v));if(i%step==0)sample.push_back(v);}if(sample.empty()||nonfinite>0)throw std::runtime_error("A library master must contain finite samples only. Repair or exclude defective source frames.");const double med=median(sample);for(auto& v:sample)v=std::abs(v-med);const double noise=1.4826*median(sample);if(image.masterRole=="Flat"&&(minimum<=1e-6||med<=0))throw std::runtime_error("Master flat contains zero or invalid illumination.");
 if(!QDir().mkpath(root()))throw std::runtime_error("Cannot create the master library.");QTemporaryDir temp(root()+"/build-XXXXXX");if(!temp.isValid())throw std::runtime_error("Cannot create master working files.");const auto file=temp.filePath("master.fits");recording::writeAstroFits(file.toStdString(),image);check(stop);auto r=calibrationMetadata(image);r["id"]=QUuid::createUuid().toString(QUuid::WithoutBraces);r["name"]=name.trimmed();r["role"]=QString::fromStdString(image.masterRole);r["date"]=QDateTime::currentDateTimeUtc().toString(Qt::ISODate);r["hash"]=calibrationFileHash(file,stop);r["median"]=med;r["noiseMAD"]=noise;r["minimum"]=minimum;r["maximum"]=maximum;r["nonPositivePercent"]=100*zero/image.samples.size();r["group"]=image.filter.empty()?(image.channels==3||image.bayer!=domain::BayerPattern::None?"RGB":"Mono"):QString::fromStdString(image.filter).toUpper();
 auto group=r["group"].toString();if(group=="RED")group="R";if(group=="GREEN")group="G";if(group=="BLUE")group="B";if(group=="LUMINANCE"||group=="LUM")group="L";if(group=="HALPHA"||group=="H-ALPHA"||group=="H_ALPHA")group="HA";r["group"]=group;
 QLockFile lock(root()+"/library.lock");if(!lock.tryLock(5000))throw std::runtime_error("Master library is in use. Retry shortly.");auto rows=inventory();if(rows.size()>=1000)throw std::runtime_error("Master library is limited to 1000 entries.");check(stop);const auto destination=root()+"/"+r["id"].toString()+".fits";if(!QFile::rename(file,destination))throw std::runtime_error("Cannot store the master file.");try{rows<<r;save(rows);}catch(...){QFile::remove(destination);throw;}r["path"]=destination;return r;
}
void removeCalibrationMaster(const QString& id){QLockFile lock(root()+"/library.lock");if(!lock.tryLock(5000))throw std::runtime_error("Master library is in use. Retry shortly.");auto rows=inventory();for(int i=0;i<rows.size();++i)if(rows[i].toMap()["id"]==id){rows.removeAt(i);save(rows);return;}throw std::runtime_error("Master not found in the library.");}
}
